]

def row_fill_with_gaps(row):
    # Find positions of 5s
    wall_positions = [i for i, v in enumerate(row) if v == 5]

    # For each consecutive pair of walls, fill the gap
    result = []
    for i in range(27):
        val = row[i]
        if val == 5:
            result.append(5)
        else:
            # Check if this is in a gap between two walls
            is_gap = False
            for j in range(len(wall_positions) - 1):
                if wall_positions[j] < i < wall_positions[j+1]:
                    is_gap = True
                    break
            if is_gap:
                result.append(3)
            else:
                result.append(val)  # stay as 8 (or wherever it is)
    return result

print("Applying row-wise gap filling to test input:")
