# Let's use BFS/DFS to find connected components of 7s (8-connected)
from collections import deque

def find_components(grid):
    rows = len(grid)
    cols = len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 7 and not visited[r][c]:
                component = []
                dq = deque([(r, c)])
                visited[r][c] = True
                while dq:
                    cr, cc = dq.popleft()
                    component.append((cr, cc))
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < rows and 0 <= nc < cols:
                                if grid[nr][nc] == 7 and not visited[nr][nc]:
                                    visited[nr][nc] = True
                                    dq.append((nr, nc))
                components.append(component)

    return components

